export const KEY='quidence-college-voice-demo-v1';
export const copy=x=>JSON.parse(JSON.stringify(x));
export const fmt=(n,d=2)=>Number(n.toFixed(d)).toString();
export function parseNumber(raw){const s=String(raw).trim().replaceAll('−','-');if(!/^[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)$/.test(s))return null;const n=Number(s.replace(',','.'));return Number.isFinite(n)?n:null;}
export function vectorModel(angle=45,transfer=false){
 const k=transfer?3:2,x=transfer?3:2*Math.cos(angle*Math.PI/180),y=transfer?4:2*Math.sin(angle*Math.PI/180);
 const before=Math.hypot(x,y),after=Math.hypot(k*x,y);return {x,y,k,before,after,factor:after/before,angle};
}
export function intervalModel(n=40,level=95){
 const mean=3.2,sigma=8,z=level===99?2.576:1.96,se=sigma/Math.sqrt(n),half=z*se;
 return {n,level,mean,sigma,z,se,half,lo:mean-half,hi:mean+half};
}
export const ids=['linear','stats','precalculus','game-theory','geometry','algebra2'];
export const defaults=id=>copy({linear:{angle:45},stats:{n:40,level:95},precalculus:{b:2,theta:30},'game-theory':{a:0,b:0},geometry:{w:3},algebra2:{x:1,b:1.5}}[id]);
export const blank=id=>({id:globalThis.crypto?.randomUUID?.()||String(Date.now())+'-'+Math.random().toString(36).slice(2),createdAt:new Date().toISOString(),phase:0,reached:0,model:defaults(id),claim:'',draft:'',first:null,samples:[],observation:'',number:'',reason:'',focus:'',review:null,correction:'',followNumber:'',followText:'',followSaved:null,transferNumber:'',transferText:'',transfer:null,reflection:'',reflectedAt:null,reflections:[],voiceSources:[]});
export function waveModel(b=2,theta=30,transfer=false){const amplitude=transfer?3:1,k=transfer?4:b,t=transfer?22.5:theta;return {amplitude,b:k,theta:t,period:360/k,cycles:k,value:amplitude*Math.sin(k*t*Math.PI/180)};}
export function rectangleModel(w=3,transfer=false){const perimeter=transfer?28:24,width=transfer?5:w,height=perimeter/2-width;return {w:width,h:height,perimeter,area:width*height,maxArea:(perimeter/4)**2};}
export function growthModel(x=1,b=1.5,transfer=false){const start=transfer?80:100,t=transfer?2:x,base=transfer?1.25:b,value=start*base**t,next=start*base**(t+1);return {start,x:t,b:base,value,next,delta:next-value,ratio:base};}
export function gameModel(a=0,b=0,transfer=false){const matrix=transfer?[[[4,4],[0,3]],[[3,0],[2,2]]]:[[[3,3],[0,5]],[[5,0],[1,1]]],row=transfer?0:a,col=transfer?0:b,own=matrix[row][col][0],other=matrix[row][col][1],switchOwn=matrix[1-row][col][0],switchOther=matrix[row][1-col][1];return {a:row,b:col,own,other,total:own+other,switchOwn,switchOther,gainOwn:switchOwn-own,gainOther:switchOther-other,stable:switchOwn<=own&&switchOther<=other?1:0};}
export function modelFor(id,s,transfer=false){switch(id){case 'linear':return vectorModel(s.model.angle,transfer);case 'stats':return intervalModel(transfer?40:s.model.n,transfer?99:s.model.level);case 'precalculus':return waveModel(s.model.b,s.model.theta,transfer);case 'geometry':return rectangleModel(s.model.w,transfer);case 'algebra2':return growthModel(s.model.x,s.model.b,transfer);case 'game-theory':return gameModel(s.model.a,s.model.b,transfer);default:throw Error('Unknown subject');}}
export const subject={
 linear:{name:'Linear Algebra',title:'Think in Vectors',subtitle:'Stretch one direction. Explain what changes.',tag:'DIRECTIONS, LENGTH & TRANSFORMATIONS',question:'“Double the horizontal coordinate, and every vector becomes twice as long.” Does that claim hold?',prompt:'Compare the two vector lengths. Explain whether a horizontal stretch by 2 doubles length in every direction.',number:'Length factor: transformed ÷ original',focus:[['universal','The claim about every direction'],['counterexample','A counterexample or a special direction'],['unsure','I am still separating the two ideas'],['custom','Keep my wording open for discussion']],transfer:'A new vector is v = (3, 4). This time T(x, y) = (3x, y). What is the length factor, and does it equal 3?',transferNumber:'New length factor',sample:[
 {name:'A common mix-up',focus:'universal',text:'The horizontal coordinate doubles, so every vector becomes twice as long.'},
 {name:'An explanation with evidence',focus:'counterexample',text:'The vertical component does not change. This vector grows by about 1.58, and a vertical vector would keep its length.'},
 {name:'An uncertain first thought',focus:'unsure',text:'I can see the arrow stretch, but I am not sure whether every direction changes by the same factor.'}
 ]},
 stats:{name:'Statistics',title:'Think with Data',subtitle:'Separate an average from the people behind it.',tag:'CONFIDENCE, VARIATION & MEANING',question:'“A 95% confidence interval contains the score changes of 95% of individual students.” Does that describe this interval?',prompt:'This interval estimates the population mean score change. Explain how it differs from a statement about individual students.',number:'Lower endpoint of the confidence interval',focus:[['individual','Individuals versus the mean'],['mean','Sample size, confidence and precision'],['coverage','What the confidence percentage describes'],['custom','Keep my wording open for discussion']],transfer:'Keep n = 40 and the sample mean at 3.2 points. Use 99% confidence instead of 95%. Find the upper endpoint, then explain what became wider and what did not.',transferNumber:'Upper endpoint of the 99% interval',sample:[
 {name:'A common mix-up',focus:'individual',text:'The interval tells us where 95 percent of the individual students’ score changes fall.'},
 {name:'An explanation with evidence',focus:'mean',text:'The interval estimates the population mean change. A larger sample can narrow that interval without making individual students more alike.'},
 {name:'A question about confidence',focus:'coverage',text:'I think the 95 percent is about the interval method, but I am not sure what repeats and what stays fixed.'}
 ]}
};
export function followup(id,focus){
 if(id==='linear'){
  if(focus==='counterexample')return {observation:'Let’s examine the special-direction argument you selected.',question:'Keep the horizontal stretch at 2 and point the vector along the horizontal axis. What is the length factor now? How does that fit with the vertical case?',label:'Length factor on the horizontal axis',target:2,probe:{angle:0},reason:'A horizontal vector has no vertical component, so its length doubles. A vertical vector keeps its length.'};
  if(focus==='custom')return {observation:'Your wording is preserved without an automatic judgment.',question:'Which direction would give the clearest test of your explanation? Use the diagram and say why you chose it.',label:null,target:null,probe:{angle:90},reason:''};
  return {observation:focus==='unsure'?'Let’s separate a change in one coordinate from a change in total length.':'The step from “horizontal coordinate” to “every length” is the claim to test.',question:'Keep the horizontal stretch at 2 and make the vector vertical. What is its length factor? What does that tell you about “every vector”?',label:'Length factor on the vertical axis',target:1,probe:{angle:90},reason:'A vertical vector has horizontal coordinate zero. The transformation leaves it unchanged, so the factor is 1.'};
 }
 if(id!=='stats')return extraFollowup(id,focus);
 if(focus==='mean')return {observation:'Let’s test the confidence-versus-precision distinction you selected.',question:'At the same sample size, switch from 95% to 99% confidence. What is the ratio of the new half-width to the old half-width? Explain the tradeoff.',label:'99% half-width ÷ 95% half-width',target:2.576/1.96,probe:{n:40,level:99},reason:'The ratio is 2.576 ÷ 1.96 ≈ 1.314. Higher confidence needs a wider interval at the same sample size.'};
 if(focus==='coverage')return {observation:'Let’s make the repeated-sampling meaning concrete.',question:'Imagine 100 independent samples and 100 intervals made by this 95% method. About how many intervals would cover the same population mean in the long run? What remains fixed?',label:'Expected number out of 100',target:95,probe:{n:40,level:95},reason:'About 95 out of 100 in the long run. The population mean is fixed; the samples and intervals vary.'};
 if(focus==='custom')return {observation:'Your wording is preserved without an automatic judgment.',question:'Are you describing individual students, the population mean, or repeated intervals? Choose the quantity you mean and connect it to the picture.',label:null,target:null,probe:{n:40,level:95},reason:''};
 return {observation:'Let’s compare individual variation with uncertainty about a mean.',question:'Compare n = 40 with n = 160. What is the ratio of the new confidence-interval half-width to the old one? Does the assumed individual standard deviation change?',label:'Half-width at n = 160 ÷ half-width at n = 40',target:.5,probe:{n:160,level:95},reason:'The ratio is √40 ÷ √160 = 0.5. The assumed individual standard deviation stays at 8 points.'};
}
export const numericMatch=(raw,target)=>{const n=parseNumber(raw);return n===null?null:Math.abs(n-target)<=.02;};
export const targetFor=(id,m,transfer=false)=>({linear:m.factor,stats:transfer?m.hi:m.lo,precalculus:m.period,geometry:m.area,algebra2:m.delta,'game-theory':transfer?m.switchOwn:m.gainOwn})[id];
export function exampleAttempt(id){
 const s=blank(id),at=new Date().toISOString(),sample=subject[id].sample[0];s.isExample=true;s.phase=s.reached=2;s.claim='0';
 s.first={text:sample.text,claim:'0',claimText:'Authored example — a first impression',model:copy(modelFor(id,s)),at};
 const settings={linear:[{angle:0},{angle:90}],stats:[{n:40,level:95},{n:160,level:95}],precalculus:[{b:1,theta:30},{b:2,theta:30}],'game-theory':[{a:0,b:0},{a:1,b:0}],geometry:[{w:3},{w:6}],algebra2:[{x:0,b:1.5},{x:1,b:1.5}]}[id];
 s.samples=settings.map(model=>({model,result:modelFor(id,{model}),at}));
 s.reason=sample.text;s.focus=sample.focus;s.number={linear:'2',stats:'0.72',precalculus:'720','game-theory':'0',geometry:'36',algebra2:'50'}[id];
 const m=modelFor(id,s),target=targetFor(id,m);s.review={text:s.reason,raw:s.number,target,matches:numericMatch(s.number,target),focus:s.focus,model:copy(m),sources:[],kind:'scripted_demo',at};
 s.voiceSources=[{field:'reason',rawText:sample.text,confirmedText:sample.text,kind:'example_transcript',model:copy(s.model),at}];return s;
}
export function validDB(db){
 const text=x=>typeof x==='string'&&x.length<=2000,object=x=>!!x&&typeof x==='object'&&!Array.isArray(x);
 const integer=(x,lo,hi)=>Number.isInteger(x)&&x>=lo&&x<=hi;
 const model=(id,m)=>object(m)&&({linear:()=>integer(m.angle,0,90)&&m.angle%15===0,stats:()=>integer(m.n,20,200)&&m.n%20===0&&[95,99].includes(m.level),precalculus:()=>integer(m.b,1,4)&&integer(m.theta,0,360)&&m.theta%15===0,'game-theory':()=>[0,1].includes(m.a)&&[0,1].includes(m.b),geometry:()=>integer(m.w,1,11),algebra2:()=>integer(m.x,0,4)&&[1.25,1.5,2].includes(m.b)})[id]();
 const response=r=>object(r)&&text(r.text)&&text(r.raw)&&((r.target===null&&r.matches===null)||(Number.isFinite(r.target)&&typeof r.matches==='boolean'))&&typeof r.at==='string';
 return object(db)&&db.version===1&&ids.filter(id=>db[id]!==undefined||['linear','stats'].includes(id)).every(id=>Array.isArray(db[id])&&db[id].length&&db[id].every(s=>
  object(s)&&typeof s.id==='string'&&typeof s.createdAt==='string'&&Number.isInteger(s.phase)&&s.phase>=0&&s.phase<5&&Number.isInteger(s.reached)&&s.reached>=s.phase&&s.reached<5&&model(id,s.model)&&
  ['draft','observation','number','reason','focus','correction','followText','followNumber','transferNumber','transferText','reflection'].every(k=>text(s[k]))&&['','0','1','2'].includes(s.claim)&&
  Array.isArray(s.samples)&&s.samples.length<=12&&s.samples.every(x=>object(x)&&model(id,x.model)&&object(x.result)&&Object.values(x.result).every(Number.isFinite)&&typeof x.at==='string')&&
  Array.isArray(s.reflections)&&s.reflections.every(x=>object(x)&&text(x.text)&&typeof x.at==='string')&&
  Array.isArray(s.voiceSources)&&s.voiceSources.every(x=>object(x)&&['draft','observation','reason','followText','correction','transferText','reflection'].includes(x.field)&&text(x.rawText)&&text(x.confirmedText)&&['example_transcript','typed_after_rehearsal'].includes(x.kind)&&model(id,x.model)&&typeof x.at==='string')&&
  (s.first===null||(object(s.first)&&text(s.first.text)&&text(s.first.claimText)&&typeof s.first.at==='string'))&&
  (s.review===null||(response(s.review)&&subject[id].focus.some(x=>x[0]===s.review.focus)))&&
  (s.followSaved===null||response(s.followSaved))&&(s.transfer===null||response(s.transfer))&&
  (s.reached<1||!!s.first)&&(s.reached<2||s.samples.length>0)&&(s.reached<3||!!s.review&&!!s.followSaved)&&(s.reached<4||!!s.transfer)
 ));
}

Object.assign(subject,{
 precalculus:{name:'Precalculus',title:'Think in Waves',subtitle:'Change the inside. Watch the whole pattern.',tag:'PERIOD, HEIGHT & HORIZONTAL SCALE',question:'“Changing sin(x) to sin(2x) doubles both the height and the period.” Does the 2 have those effects?',choices:['Yes, both become twice as large.','No, the inside changes the horizontal scale.','I want to test it.'],evidence:'Compare sin(x) with sin(bx). Keep one setting for b = 1 and another for b = 2. Track a complete cycle and the highest point.',prompt:'For the highlighted curve y = sin(2x), find the period in degrees. Explain what changed horizontally and what happened to the amplitude.',number:'Period of the highlighted curve (degrees)',focus:[['period','Period versus the inside multiplier'],['height','Amplitude versus frequency'],['unsure','Counting complete cycles'],['custom','Keep my wording open for discussion']],transfer:'A fresh curve is y = 3 sin(4x), with x in degrees. Find its period, then explain separately what the 3 and the 4 do.',transferNumber:'Period of the new curve (degrees)',sample:[{name:'A common mix-up',focus:'period',text:'The 2 doubles the height and stretches the original 360-degree period to 720 degrees.'},{name:'An explanation with evidence',focus:'height',text:'The inside multiplier makes the curve complete two cycles in 360 degrees. Its period is 180 degrees, and its amplitude stays at 1.'},{name:'An uncertain first thought',focus:'unsure',text:'I see more waves, but I am still separating the number of cycles from the height of each wave.'}]},
 'game-theory':{name:'Game Theory',title:'Think in Choices',subtitle:'A good shared outcome still needs a reason to stay.',tag:'PAYOFFS, INCENTIVES & STABILITY',question:'“The outcome with the highest combined payoff must be stable: neither player would change alone.” Does the payoff table support that?',choices:['Yes, the best combined score must be stable.','No, check each player’s incentive to change.','I want to test it.'],evidence:'Start with both players cooperating. Hold the other player’s move fixed and change only your move. Then compare this with both players competing.',prompt:'Start with both players cooperating. How much does your payoff increase if you alone switch to Compete? Explain why the combined payoff is a different question.',number:'Your payoff increase after switching alone',focus:[['joint','Combined benefit versus a personal incentive'],['stable','Checking a Nash equilibrium'],['unsure','Holding the other player’s move fixed'],['custom','Keep my wording open for discussion']],transfer:'The new coordination game has different payoffs. Both players currently choose Risky. What would your payoff be if you alone switched to Safe? Explain whether a unilateral switch would help, and whether this is the only stable outcome.',transferNumber:'Your payoff after switching alone to Safe',sample:[{name:'A common mix-up',focus:'joint',text:'Both cooperating gives the highest combined payoff, so neither player has a reason to change.'},{name:'An explanation with evidence',focus:'stable',text:'Cooperating together gives a total of 6, but I can raise my own payoff from 3 to 5 by switching alone. Both competing is stable even though its total is only 2.'},{name:'An uncertain first thought',focus:'unsure',text:'I am not sure whether stability means the highest total or the best move while the other player stays put.'}]},
 geometry:{name:'Geometry',title:'Think in Shapes',subtitle:'Keep the boundary. Let the inside change.',tag:'PERIMETER, AREA & WHAT STAYS FIXED',question:'“Rectangles with the same perimeter always have the same area.” Can changing the side lengths test that claim?',choices:['Yes, the same boundary gives the same area.','No, the product of the side lengths can change.','I want to test it.'],evidence:'The perimeter stays at 24 units. Change the width and watch the height adjust. Compare a long, narrow rectangle with the square.',prompt:'A rectangle has perimeter 24 units, width 3 and height 9. Find its area and explain whether the fixed perimeter forces a fixed area.',number:'Area (square units)',focus:[['boundary','A fixed sum versus a changing product'],['square','Why the square is special'],['unsure','Comparing two rectangles'],['custom','Keep my wording open for discussion']],transfer:'Now the perimeter is 28 units. The width is 5 and the height is 9. Find the area, then compare it with the square that has this same perimeter.',transferNumber:'Area of the new rectangle (square units)',sample:[{name:'A common mix-up',focus:'boundary',text:'All rectangles with perimeter 24 must have area 36 because the boundary is fixed.'},{name:'An explanation with evidence',focus:'square',text:'The side lengths add to 12, but their product changes. The 3-by-9 rectangle has area 27, while the 6-by-6 square has area 36.'},{name:'An uncertain first thought',focus:'unsure',text:'The boundary stays the same, but the space inside looks different. I want to compare the products.'}]},
 algebra2:{name:'Algebra II',title:'Think in Growth',subtitle:'A repeated multiplier makes changing differences.',tag:'EXPONENTIAL RULES, DIFFERENCES & RATIOS',question:'“For f(x) = 100 × 1.5ˣ, each one-step increase in x adds 50.” Does the first step tell us every later step?',choices:['Yes, every one-step increase adds 50.','No, the multiplier stays fixed, not the difference.','I want to test it.'],evidence:'Compare consecutive values at x = 0 and x = 1, then try a later step. Track both the added amount and the ratio.',prompt:'For f(x) = 100 × 1.5ˣ, compare x = 1 with x = 2. Find the added amount and explain what stays constant from step to step.',number:'Added amount: f(2) − f(1)',focus:[['difference','A fixed difference versus a fixed ratio'],['ratio','Using the multiplier across several steps'],['unsure','Checking a later increase'],['custom','Keep my wording open for discussion']],transfer:'A new function is g(x) = 80 × 1.25ˣ. Compare x = 2 with x = 3. Find the added amount, then explain how the starting value and multiplier play different roles.',transferNumber:'Added amount: g(3) − g(2)',sample:[{name:'A common mix-up',focus:'difference',text:'It starts at 100 and becomes 150, so the function adds 50 every time x increases by one.'},{name:'An explanation with evidence',focus:'ratio',text:'The values 100, 150 and 225 have a fixed ratio of 1.5. Their differences are 50 and 75, so the added amount is not fixed.'},{name:'An uncertain first thought',focus:'unsure',text:'I can see growth, but I need to compare the added amount with the multiplier at a later step.'}]}
});
export function extraFollowup(id,focus){
 const custom={observation:'Your wording is preserved without an automatic judgment.',question:'Which setting gives the clearest test of your explanation? Use the model, keep the quantities separate, and explain why you chose it.',label:null,target:null,probe:defaults(id),reason:''};if(focus==='custom')return custom;
 const cases={
 precalculus:{period:{observation:'Let’s test the relationship between the inside multiplier and one complete cycle.',question:'Change to y = sin(4x). How many degrees does one cycle take? Explain why multiplying the input compresses the horizontal pattern.',label:'Period when b = 4 (degrees)',target:90,probe:{b:4,theta:30},reason:'A cycle occurs when 4x increases by 360 degrees, so x increases by 90 degrees.'},height:{observation:'Let’s check the peak separately from the cycle length.',question:'Keep y = sin(2x) and set x = 45°. What is y? How does that peak compare with the amplitude of sin(x)?',label:'Value of sin(2x) at x = 45°',target:1,probe:{b:2,theta:45},reason:'sin(90°) = 1. The input multiplier changes the period, while the amplitude remains 1.'},unsure:{observation:'Let’s count a full repeated pattern.',question:'For y = sin(2x), how many complete cycles fit from x = 0° to 360°? Connect that count to a 180° period.',label:'Complete cycles from 0° to 360°',target:2,probe:{b:2,theta:360},reason:'Two complete cycles fit into 360 degrees, each lasting 180 degrees.'}},
 'game-theory':{joint:{observation:'Let’s keep the other player’s move fixed and compare your payoffs.',question:'Hold the other player at Compete. How much higher is your payoff from Compete than from Cooperate? Does choosing the best personal response maximize the total?',label:'Compete payoff minus Cooperate payoff',target:1,probe:{a:1,b:1},reason:'Against Compete, your payoffs are 1 from Compete and 0 from Cooperate. Both competing is the unique pure Nash equilibrium here, but both cooperating has the larger total.'},stable:{observation:'Let’s test stability with a single-player deviation.',question:'Start with both players competing. What payoff would you get if you alone changed to Cooperate? Explain why the original outcome is stable.',label:'Your payoff after switching alone to Cooperate',target:0,probe:{a:0,b:1},reason:'Your payoff falls from 1 to 0. The other player faces the same comparison, so neither benefits from changing alone.'},unsure:{observation:'Let’s change one move at a time.',question:'Start with both players cooperating and hold the other player fixed. What is your payoff after you alone choose Compete?',label:'Your payoff from Compete against Cooperate',target:5,probe:{a:1,b:0},reason:'The payoff pair is (5, 0). A unilateral change means the other player’s action stays fixed.'}},
 geometry:{boundary:{observation:'Let’s compare the same perimeter with a different product.',question:'Keep the perimeter at 24 and make the width 6. What is the area now? Compare it with the original 3-by-9 rectangle.',label:'Area when the width is 6',target:36,probe:{w:6},reason:'The height is also 6, giving 36 square units rather than 27. The perimeter fixes a sum of side lengths, not their product.'},square:{observation:'Let’s move away from the square while keeping the perimeter fixed.',question:'Set the width to 2. What is the area? Use the identity A = w(12 − w) = 36 − (w − 6)² to explain why the square has the maximum area.',label:'Area when the width is 2',target:20,probe:{w:2},reason:'The height is 10 and the area is 20. Since (w − 6)² is nonnegative, the area cannot exceed 36.'},unsure:{observation:'Let’s make a second rectangle with the same boundary.',question:'Set the width to 4. The height must be 8 to keep the perimeter at 24. What area does this give, compared with 27 before?',label:'Area of the 4-by-8 rectangle',target:32,probe:{w:4},reason:'4 × 8 = 32 square units, despite the unchanged perimeter.'}},
 algebra2:{difference:{observation:'Let’s separate a repeated multiplier from a repeated added amount.',question:'Return to x = 0 with multiplier 1.5. What is the ratio f(1) ÷ f(0)? Explain why that ratio stays fixed even when the added amount changes.',label:'Ratio f(1) ÷ f(0)',target:1.5,probe:{x:0,b:1.5},reason:'150 ÷ 100 = 1.5. Each step multiplies the current value by 1.5; it adds half of that current value.'},ratio:{observation:'Let’s use the multiplier across two steps.',question:'From x = 0 to x = 2, what is the total multiplicative factor? Explain why it is 1.5² rather than 1.5 + 1.5.',label:'Two-step multiplicative factor',target:2.25,probe:{x:1,b:1.5},reason:'100 × 1.5 × 1.5 = 225, so the overall factor is 2.25.'},unsure:{observation:'Let’s check a later increase numerically.',question:'Compare x = 3 with x = 4, keeping the multiplier at 1.5. How much is added? Does the original “add 50” rule still work?',label:'Added amount f(4) − f(3)',target:168.75,probe:{x:3,b:1.5},reason:'506.25 − 337.5 = 168.75. The difference grows because each step adds 50% of the current value.'}}
 };return cases[id]?.[focus]||custom;
}
export function checkpointCopy(id,m){
 switch(id){
 case 'precalculus':return {prompt:'For the highlighted curve y = '+(m.amplitude===1?'':m.amplitude+' ')+'sin('+m.b+'x), find the period in degrees. Explain what changed horizontally and what happened to the amplitude.',label:'Period of the highlighted curve (degrees)'};
 case 'geometry':return {prompt:'This rectangle has perimeter '+m.perimeter+' units, width '+m.w+' and height '+m.h+'. Find its area and explain whether the fixed perimeter forces a fixed area.',label:'Area (square units)'};
 case 'algebra2':return {prompt:'For f(x) = '+m.start+' × '+m.b+'ˣ, compare x = '+m.x+' with x = '+(m.x+1)+'. Find the added amount and explain what stays constant from step to step.',label:'Added amount: f('+(m.x+1)+') − f('+m.x+')'};
 case 'game-theory':return {prompt:'You currently choose '+(m.a===0?'Cooperate':'Compete')+' and the other player chooses '+(m.b===0?'Cooperate':'Compete')+'. How does your payoff change if you alone switch your move? A decrease is negative. Explain why the combined payoff is a different question.',label:'Your payoff change after switching alone'};
 default:return {prompt:subject[id].prompt,label:subject[id].number};
 }
}
